describe('Pagination Controls - Load Correct Page of Results', () => {
  beforeEach(() => {
    cy.visit('/results');
  });

  it('should load the correct page of results when clicking pagination buttons', () => {
    // Verify initial state - Page 1
    cy.get('[data-testid="results-list"]').should('be.visible');
    cy.get('[data-testid="results-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="page-indicator"]').should('contain', 'Page 1');

    // Click next page button
    cy.get('[data-testid="pagination-next-button"]').click();

    // Verify page 2 loaded
    cy.get('[data-testid="page-indicator"]').should('contain', 'Page 2');
    cy.get('[data-testid="results-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="results-item"]').first().should('contain', 'Result 11');

    // Click previous page button
    cy.get('[data-testid="pagination-prev-button"]').click();

    // Verify page 1 loaded again
    cy.get('[data-testid="page-indicator"]').should('contain', 'Page 1');
    cy.get('[data-testid="results-item"]').first().should('contain', 'Result 1');

    // Click page 3 button directly
    cy.get('[data-testid="pagination-page-3-button"]').click();

    // Verify page 3 loaded
    cy.get('[data-testid="page-indicator"]').should('contain', 'Page 3');
    cy.get('[data-testid="results-item"]').first().should('contain', 'Result 21');
  });

  it('should handle edge case of navigating to last page and disabled buttons', () => {
    // Navigate to last page (Page 5)
    cy.get('[data-testid="pagination-page-5-button"]').click();
    cy.get('[data-testid="page-indicator"]').should('contain', 'Page 5');

    // Verify last page results are displayed
    cy.get('[data-testid="results-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="results-item"]').first().should('contain', 'Result 40');

    // Verify next button is disabled on last page
    cy.get('[data-testid="pagination-next-button"]').should('be.disabled');
    cy.get('[data-testid="pagination-next-button"]').should('have.attr', 'disabled');

    // Verify previous button is enabled
    cy.get('[data-testid="pagination-prev-button"]').should('not.be.disabled');

    // Click previous button
    cy.get('[data-testid="pagination-prev-button"]').click();

    // Verify page 4 loaded
    cy.get('[data-testid="page-indicator"]').should('contain', 'Page 4');
    cy.get('[data-testid="results-item"]').first().should('contain', 'Result 29');

    // Verify next button is enabled on page 4
    cy.get('[data-testid="pagination-next-button"]').should('not.be.disabled');
    cy.get('[data-testid="pagination-next-button"]').should('not.have.attr', 'disabled');
  });
});
